import { resolve } from "node:path";
import { Policy } from "../../policy/src/index.ts";
import { AgentManager, createPiRunner, registerAgents } from "../../agents/src/index.ts";
import { MCPManager } from "../../mcp/src/index.ts";
import { registerSwarmPrompt } from "./swarm-prompt.ts";

type RuntimeState = { initialized: boolean; cwd: string; agents?: AgentManager; policy?: Policy; mcp?: MCPManager; };
const runtimeByPi = new WeakMap<object, RuntimeState>();

type Pi = any;

/** Single integration boundary for the Pi-Swarm extensions. */
export function registerSwarmRuntime(pi: Pi, options: { cwd?: string; closed?: boolean; allowedTools?: string[]; allowedSkills?: string[]; allowMutation?: boolean; allowNetwork?: boolean } = {}): RuntimeState {
  const cwd = resolve(options.cwd ?? pi.getCwd?.() ?? process.cwd());
  const existing = runtimeByPi.get(pi as object);
  if (existing?.initialized && existing.cwd === cwd) return existing;
  const state: RuntimeState = { initialized: true, cwd };
  runtimeByPi.set(pi as object, state);

  // Establish prompt and resource policy before feature registration.
  registerSwarmPrompt(pi);
  state.policy = new Policy({ workspace: cwd, allowedTools: options.allowedTools, allowMutation: options.allowMutation, allowNetwork: options.allowNetwork });

  // Dedicated extensions own tool registration; the umbrella only owns shared
  // policy/identity and must never register duplicate tools.

  state.agents = registerAgents(pi, new AgentManager({ cwd, concurrency: 4, runner: createPiRunner(pi) }));
  pi.on?.("session_shutdown", () => state.mcp?.close());
  const manifests = pi.mcpManifests ?? [];
  if (Array.isArray(manifests)) state.mcp = new MCPManager(manifests, { closed: options.closed ?? true, registerTool: tool => pi.registerTool(tool) });
  pi.registerCommand?.("swarm-runtime", { description: "Inspect integrated Pi-Swarm runtime", handler: async (_args: string, ctx: any) => ctx.ui?.notify?.(`Pi-Swarm runtime active at ${cwd}; mcp=${manifests.length}`, "info") });
  return state;
}

export default function swarmRuntimeExtension(pi: Pi) { return registerSwarmRuntime(pi); }
import {
  registerTaskHooks,
  registerTaskManage,
  type HookConfig,
  registerInteractionTools,
} from "../../taskmanage/src/index.ts";
import "../hook-state.ts";

/**
 * Minimal structural subset of Pi's ExtensionAPI used by TaskManage.
 *
 * Keeping this adapter structural means the standalone package does not need
 * to depend on a particular Pi release just to remain buildable and testable.
 */
export interface TaskManageExtensionAPI {
  registerTool(tool: unknown): void;
  appendEntry(type: string, data: unknown): void;
  on(
    event: string,
    handler: (
      event: unknown,
      ctx: { sessionManager?: { getEntries(): readonly unknown[] } },
    ) => unknown,
  ): void;
}

export interface TaskManageExtensionOptions extends HookConfig { headless?: boolean; interactionTimeoutMs?: number; }

/**
 * Register the canonical TaskManage tool and its lifecycle coordinator.
 *
 * The manager is intentionally created once per Pi extension instance and is
 * shared by both registrations. Pi reloads create a new instance; the
 * session_start handler rehydrates it from the replacement session manager.
 */
const taskRuntimeByPi = new WeakMap<object, { manager: any; hooks: any; interactions: any }>();
export function registerTaskManageExtension(
  pi: TaskManageExtensionAPI,
  options?: TaskManageExtensionOptions,
) {
  const owner = pi as object;
  const existing = taskRuntimeByPi.get(owner);
  if (existing) return existing;
  const manager = registerTaskManage(pi);
  const hooks = registerTaskHooks(pi, manager, options);
  const interactions = registerInteractionTools(pi as any, { headless: options?.headless, timeoutMs: options?.interactionTimeoutMs });
  const result = { manager, hooks, interactions };
  taskRuntimeByPi.set(owner, result);
  return result;
}

export default function taskManageExtension(pi: TaskManageExtensionAPI): void {
  registerTaskManageExtension(pi);
}
